"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two rules drive the implementation:

* Addresses and lengths are reported exactly as the system reports them. No
  masking, no rounding: a region above 4 GiB keeps its real base and a 6 GiB
  reservation keeps its real length.
* A path is only reported when the caller can open it. The kernel names a
  mapped file ``\\Device\\HarddiskVolume5\\...``; that is translated to a DOS
  drive or UNC path, and when no translation exists the path is ``None``.
"""

import ctypes
import sys

from . import _winapi as w
from .errors import WVasError

#: Win32 paths can reach 32767 characters, so the lookup buffers are sized for
#: the worst case rather than for legacy ``MAX_PATH``.
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

_POINTER_BITS = ctypes.sizeof(ctypes.c_void_p) * 8
_DEFAULT_MAX_ADDRESS = 0x7FFFFFFEFFFF if _POINTER_BITS == 64 else 0x7FFEFFFF

_UNC_DEVICE_PREFIXES = (
    "\\device\\mup\\",
    "\\device\\lanmanredirector\\",
    "\\device\\webdavredirector\\",
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# process handles
# ---------------------------------------------------------------------------

def _require_platform(pid=None):
    if sys.platform != "win32" or not w.AVAILABLE:
        raise WVasError(
            "address space auditing is only available on Windows",
            kind="unsupported",
            pid=pid,
        )


def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid > 0xFFFFFFFF:
        raise WVasError("pid is out of range", kind="badarg", pid=pid)


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _validate_pid(pid)
    _require_platform(pid)

    wanted = (w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ,
              w.PROCESS_QUERY_LIMITED_INFORMATION | w.PROCESS_VM_READ,
              w.PROCESS_QUERY_LIMITED_INFORMATION)
    error = 0
    for access in wanted:
        ctypes.set_last_error(0)
        handle = w.OpenProcess(access, False, pid)
        if handle:
            return handle
        error = w.last_error()
        if error != w.ERROR_ACCESS_DENIED:
            break

    if error == w.ERROR_INVALID_PARAMETER:
        raise WVasError(
            "no such process", kind="no-such-process", pid=pid
        )
    if error == w.ERROR_ACCESS_DENIED:
        raise WVasError(
            "the process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    raise WVasError(
        "OpenProcess failed with error %d" % (error,),
        kind="query-failed",
        pid=pid,
    )


def _close(handle):
    if handle:
        w.CloseHandle(handle)


# ---------------------------------------------------------------------------
# path translation
# ---------------------------------------------------------------------------

def _query_dos_device(name):
    size = 512
    while size <= PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.QueryDosDeviceW(name, buffer, size)
        if written:
            # The result is a NUL separated list; the first entry is the one
            # the drive letter currently resolves to.
            return buffer[:written].split("\x00")[0] or None
        if w.last_error() != w.ERROR_INSUFFICIENT_BUFFER:
            return None
        size *= 4
    return None


def _device_map():
    """Return ``[(device_name_lowercase, dos_prefix), ...]``, longest first."""
    size = 256
    drives = ""
    while size <= 4096:
        buffer = ctypes.create_unicode_buffer(size)
        written = w.GetLogicalDriveStringsW(size, buffer)
        if written and written < size:
            drives = buffer[:written]
            break
        if not written:
            return []
        size = written + 1
    mapping = []
    for entry in drives.split("\x00"):
        letter = entry.strip().rstrip("\\")
        if len(letter) != 2 or letter[1] != ":":
            continue
        device = _query_dos_device(letter)
        if not device:
            continue
        mapping.append((device.rstrip("\\").lower(), letter))
    mapping.sort(key=lambda item: len(item[0]), reverse=True)
    return mapping


def _strip_extended_prefix(path):
    for prefix in ("\\\\?\\", "\\??\\"):
        if path.startswith(prefix):
            rest = path[len(prefix):]
            if rest[:4].upper() == "UNC\\":
                return "\\\\" + rest[4:]
            return rest
    return path


def _openable_path(path, device_map):
    """Translate a kernel path into something the caller can open.

    Returns ``None`` when no DOS drive or UNC equivalent exists, rather than
    handing back a ``\\Device\\...`` name that nobody can use.
    """
    if not path:
        return None
    path = _strip_extended_prefix(path)
    if not path:
        return None

    # Already a drive path such as ``C:\windows\...``.
    if len(path) >= 2 and path[1] == ":" and path[0].isalpha():
        return path
    # Already a UNC path such as ``\\server\share\...``.
    if path.startswith("\\\\"):
        return path

    lowered = path.lower()
    for device, letter in device_map:
        if not lowered.startswith(device):
            continue
        rest = path[len(device):]
        if rest and not rest.startswith("\\"):
            continue
        if device.startswith("\\device\\lanmanredirector")  \
                or device.startswith("\\device\\mup"):
            # A mapped network drive: prefer the letter, it opens fine.
            return letter + (rest or "\\")
        return letter + (rest or "\\")

    for prefix in _UNC_DEVICE_PREFIXES:
        if lowered.startswith(prefix):
            rest = path[len(prefix):]
            if rest.startswith(";"):
                # ``;Z:0000000000000000\server\share\...``
                cut = rest.find("\\")
                if cut < 0:
                    return None
                rest = rest[cut + 1:]
            rest = rest.lstrip("\\")
            return "\\\\" + rest if rest else None

    return None


# ---------------------------------------------------------------------------
# region walking
# ---------------------------------------------------------------------------

def _max_application_address():
    info = w.SYSTEM_INFO()
    try:
        w.GetNativeSystemInfo(ctypes.byref(info))
    except OSError:  # pragma: no cover - defensive
        return _DEFAULT_MAX_ADDRESS
    limit = int(info.lpMaximumApplicationAddress or 0)
    if limit <= 0:
        return _DEFAULT_MAX_ADDRESS
    return max(limit, _DEFAULT_MAX_ADDRESS)


def _walk(handle, pid):
    """Yield one raw snapshot per region of the target address space.

    Every value comes straight out of ``MEMORY_BASIC_INFORMATION``, so bases
    and sizes keep the full width of the target's address space.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    struct_size = ctypes.sizeof(mbi)
    limit = _max_application_address()
    address = 0
    seen_any = False

    while address <= limit:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle,
            ctypes.c_void_p(address),
            ctypes.byref(mbi),
            struct_size,
        )
        if not written:
            error = w.last_error()
            if not seen_any and error not in (
                w.ERROR_SUCCESS, w.ERROR_INVALID_PARAMETER
            ):
                raise WVasError(
                    "VirtualQueryEx failed with error %d" % (error,),
                    kind="query-failed",
                    pid=pid,
                )
            return
        seen_any = True

        base = int(mbi.BaseAddress or 0)
        size = int(mbi.RegionSize)
        yield {
            "base": base,
            "size": size,
            "state": int(mbi.State),
            "protect": int(mbi.Protect),
            "type": int(mbi.Type),
            "allocation_base": int(mbi.AllocationBase or 0),
        }

        if size <= 0:
            return
        next_address = base + size
        if next_address <= address:
            return
        address = next_address


def _mapped_file_name(handle, address):
    if not address:
        return None
    size = 1024
    while size <= PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, size
        )
        if not written:
            return None
        if written >= size - 1:
            size *= 4
            continue
        return buffer.value or None
    return None


def _region_path(handle, raw, device_map, cache):
    """Return the openable path of the file behind ``raw``, or ``None``."""
    if raw["type"] not in (w.MEM_IMAGE, w.MEM_MAPPED):
        return None

    allocation_base = raw["allocation_base"]
    if allocation_base in cache:
        return cache[allocation_base]

    name = _mapped_file_name(handle, raw["base"])
    if name is None and allocation_base and allocation_base != raw["base"]:
        # Uncommitted pages inside a mapped allocation cannot be named, but
        # the head of the allocation can.
        name = _mapped_file_name(handle, allocation_base)

    path = _openable_path(name, device_map)
    if allocation_base:
        cache[allocation_base] = path
    return path


def _describe(handle, raw, device_map, cache):
    return {
        "base": raw["base"],
        "size": raw["size"],
        "state": "commit" if raw["state"] == w.MEM_COMMIT else "reserve",
        "type": type_name(raw["type"]),
        "protect": protection_name(raw["protect"]),
        "path": _region_path(handle, raw, device_map, cache),
        "image": raw["type"] == w.MEM_IMAGE,
    }


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``. Committed regions are always reported;
    reserved-but-uncommitted ranges are reported as well unless
    ``include_reserved`` is false.
    """
    handle = _open_process(pid)
    try:
        wanted = (w.MEM_COMMIT, w.MEM_RESERVE) if include_reserved \
            else (w.MEM_COMMIT,)
        device_map = _device_map()
        cache = {}
        result = [
            _describe(handle, raw, device_map, cache)
            for raw in _walk(handle, pid)
            if raw["state"] in wanted
        ]
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def _enumerate_modules(handle):
    """Return the module handles of the target, or ``None`` when unavailable."""
    if w.EnumProcessModulesEx is None:  # pragma: no cover - legacy systems
        return None
    count = 256
    while count <= 1 << 20:
        array = (w.HMODULE * count)()
        needed = w.DWORD(0)
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        entry_size = ctypes.sizeof(w.HMODULE)
        found = needed.value // entry_size if entry_size else 0
        if found <= count:
            return [int(array[index] or 0) for index in range(found)]
        count = found + 32
    return None  # pragma: no cover - absurd module count


def _module_file_name(handle, module, device_map):
    size = 1024
    while size <= PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetModuleFileNameExW(
            handle, ctypes.c_void_p(module), buffer, size
        )
        if not written:
            return None
        if written >= size - 1:
            size *= 4
            continue
        return _openable_path(buffer.value, device_map)
    return None


def _module_size(handle, module):
    info = w.MODULEINFO()
    ctypes.set_last_error(0)
    if not w.GetModuleInformation(
        handle, ctypes.c_void_p(module), ctypes.byref(info), ctypes.sizeof(info)
    ):
        return None
    return int(info.SizeOfImage)


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once. The loader's module list is the primary
    source; the region walk fills in images the loader list does not mention,
    so a mapped image is never silently dropped. ``path`` is ``None`` for the
    rare image whose file cannot be named as an openable path.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        cache = {}
        found = {}

        # Images as the region walk sees them: one entry per image allocation,
        # spanning all of its regions.
        for raw in _walk(handle, pid):
            if raw["type"] != w.MEM_IMAGE:
                continue
            base = raw["allocation_base"] or raw["base"]
            end = raw["base"] + raw["size"]
            entry = found.get(base)
            if entry is None:
                found[base] = {
                    "path": _region_path(handle, raw, device_map, cache),
                    "base": base,
                    "size": end - base,
                }
            elif end - base > entry["size"]:
                entry["size"] = end - base

        # The loader's view wins on both the path and the image size.
        for module in _enumerate_modules(handle) or ():
            if not module:
                continue
            path = _module_file_name(handle, module, device_map)
            size = _module_size(handle, module)
            entry = found.get(module)
            if entry is None:
                found[module] = {
                    "path": path,
                    "base": module,
                    "size": size if size else 0,
                }
            else:
                if path is not None:
                    entry["path"] = path
                if size:
                    entry["size"] = size

        result = []
        seen_paths = set()
        for entry in sorted(found.values(), key=lambda item: item["base"]):
            if entry["path"] is not None:
                key = entry["path"].lower()
                if key in seen_paths:
                    continue
                seen_paths.add(key)
            result.append(
                {"path": entry["path"], "base": entry["base"],
                 "size": entry["size"]}
            )
        return result
    finally:
        _close(handle)

