        "OpenProcess failed with error %d" % (error,),
        kind="query-failed",
        pid=pid,
    )


def _has_exited(handle):
    """Report whether the opened process has already terminated."""
    if w.GetExitCodeProcess is None:  # pragma: no cover - defensive
        return False
    status = w.DWORD(0)
    if not w.GetExitCodeProcess(handle, ctypes.byref(status)):
        return False
    return status.value != w.STILL_ACTIVE


def _classify_query_failure(handle, pid, call, error):
    """Turn a failed Win32 query into the right :class:`WVasError`."""
    if _has_exited(handle):
        return WVasError("no such process", kind="no-such-process", pid=pid)
    if error == w.ERROR_ACCESS_DENIED:
        return WVasError(
            "the process cannot be read", kind="access-denied", pid=pid
        )
    if error == w.ERROR_INVALID_HANDLE:
        return WVasError("no such process", kind="no-such-process", pid=pid)
    return WVasError(
        "%s failed with error %d" % (call, error),
        kind="query-failed",
        pid=pid,
    )


