    info = w.SYSTEM_INFO()
    try:
        w.GetNativeSystemInfo(ctypes.byref(info))
    except OSError:  # pragma: no cover - defensive
        return _DEFAULT_MAX_ADDRESS
    limit = int(info.lpMaximumApplicationAddress or 0)
    if limit <= 0:
        return _DEFAULT_MAX_ADDRESS
    return max(limit, _DEFAULT_MAX_ADDRESS)


def _walk(handle, pid):
    """Yield one raw snapshot per region of the target address space.

    Every value comes straight out of ``MEMORY_BASIC_INFORMATION``, so bases
    and sizes keep the full width of the target's address space.
    """
    mbi = w.MEMORY_BASIC_INFORMATION()
    struct_size = ctypes.sizeof(mbi)
    limit = _max_application_address()
    address = 0
    seen_any = False

    while address <= limit:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle,
            ctypes.c_void_p(address),
            ctypes.byref(mbi),
            struct_size,
        )
        if not written:
            error = w.last_error()
            if seen_any or error in (w.ERROR_SUCCESS, w.ERROR_INVALID_PARAMETER):
                # A refused address past the end of the user range simply ends
                # the walk; the regions gathered so far are the answer.
                if seen_any or not _has_exited(handle):
                    return
            raise _classify_query_failure(
                handle, pid, "VirtualQueryEx", error
            )
        seen_any = True

        base = int(mbi.BaseAddress or 0)
        size = int(mbi.RegionSize)
        yield {
            "base": base,
            "size": size,
            "state": int(mbi.State),
            "protect": int(mbi.Protect),
            "type": int(mbi.Type),
            "allocation_base": int(mbi.AllocationBase or 0),
        }

        if size <= 0:
            return
        next_address = base + size
        if next_address <= address:
            return
        address = next_address


def _mapped_file_name(handle, address):
    if not address:
        return None
    size = 1024
    while size <= PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, size
        )
        if not written:
            return None
        if written >= size - 1:
            size *= 4
            continue
        return buffer.value or None
    return None


def _region_path(handle, raw, device_map, cache):
    """Return the openable path of the file behind ``raw``, or ``None``."""
    if raw["type"] not in (w.MEM_IMAGE, w.MEM_MAPPED):
        return None

    allocation_base = raw["allocation_base"]
    if allocation_base in cache:
        return cache[allocation_base]

    name = _mapped_file_name(handle, raw["base"])
    if name is None and allocation_base and allocation_base != raw["base"]:
        # Uncommitted pages inside a mapped allocation cannot be named, but
        # the head of the allocation can.
        name = _mapped_file_name(handle, allocation_base)

    path = _openable_path(name, device_map)
    if allocation_base:
        cache[allocation_base] = path
    return path


def _describe(handle, raw, device_map, cache):
    return {
        "base": raw["base"],
        "size": raw["size"],
        "state": "commit" if raw["state"] == w.MEM_COMMIT else "reserve",
        "type": type_name(raw["type"]),
        "protect": protection_name(raw["protect"]),
        "path": _region_path(handle, raw, device_map, cache),
        "image": raw["type"] == w.MEM_IMAGE,
    }


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The list is ascending by ``base``. Committed regions are always reported;
    reserved-but-uncommitted ranges are reported as well unless
    ``include_reserved`` is false.
    """
    handle = _open_process(pid)
    try:
        wanted = (w.MEM_COMMIT, w.MEM_RESERVE) if include_reserved \
            else (w.MEM_COMMIT,)
        device_map = _device_map()
        cache = {}
        result = [
            _describe(handle, raw, device_map, cache)
            for raw in _walk(handle, pid)
            if raw["state"] in wanted
        ]
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def _enumerate_modules(handle):
    """Return the module handles of the target, or ``None`` when unavailable."""
    if w.EnumProcessModulesEx is None:  # pragma: no cover - legacy systems
        return None
    count = 256
    while count <= 1 << 20:
        array = (w.HMODULE * count)()
        needed = w.DWORD(0)
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return None
        entry_size = ctypes.sizeof(w.HMODULE)
        found = needed.value // entry_size if entry_size else 0
        if found <= count:
            return [int(array[index] or 0) for index in range(found)]
        count = found + 32
    return None  # pragma: no cover - absurd module count


def _module_file_name(handle, module, device_map):
    size = 1024
    while size <= PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(size)
        ctypes.set_last_error(0)
        written = w.GetModuleFileNameExW(
            handle, ctypes.c_void_p(module), buffer, size
        )
        if not written:
            return None
        if written >= size - 1:
            size *= 4
            continue
        return _openable_path(buffer.value, device_map)
    return None


def _module_size(handle, module):
    info = w.MODULEINFO()
    ctypes.set_last_error(0)
    if not w.GetModuleInformation(
        handle, ctypes.c_void_p(module), ctypes.byref(info), ctypes.sizeof(info)
    ):
        return None
    return int(info.SizeOfImage)


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is listed twice. The
    region walk finds every image mapping, the loader's module list supplies
    the authoritative file name and image size, so an image is never dropped
    just because one of the two sources cannot name it. ``path`` is ``None``
    for the rare image whose file has no openable name.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        cache = {}
        found = {}

        # Images as the region walk sees them: one entry per image allocation,
        # spanning all of its regions.
        for raw in _walk(handle, pid):
            if raw["type"] != w.MEM_IMAGE:
                continue
            base = raw["allocation_base"] or raw["base"]
            end = raw["base"] + raw["size"]
            entry = found.get(base)
            if entry is None:
                found[base] = {
                    "path": _region_path(handle, raw, device_map, cache),
                    "base": base,
                    "size": end - base,
                }
            elif end - base > entry["size"]:
                entry["size"] = end - base

        # The loader's view wins on both the path and the image size.
        for module in _enumerate_modules(handle) or ():
            if not module:
                continue
            path = _module_file_name(handle, module, device_map)
            size = _module_size(handle, module)
            entry = found.get(module)
            if entry is None:
                found[module] = {
                    "path": path,
                    "base": module,
                    "size": size if size else 0,
                }
            else:
                if path is not None:
                    entry["path"] = path
                if size:
                    entry["size"] = size

        result = []
        seen_paths = set()
        for entry in sorted(found.values(), key=lambda item: item["base"]):
            if entry["path"] is not None:
                key = entry["path"].lower()
                if key in seen_paths:
                    continue
                seen_paths.add(key)
            result.append(
                {"path": entry["path"], "base": entry["base"],
                 "size": entry["size"]}
            )
        return result
    finally:
        _close(handle)

