import subprocess
import sys

import wvas

proc = subprocess.Popen([sys.executable, "_tgt.py", "_tgt.py"], stdout=subprocess.PIPE, text=True)
pid = int(proc.stdout.readline().split()[0])
try:
    regs = wvas.regions(pid)
    mods = wvas.modules(pid)
    mod_bases = {m["base"] for m in mods}
    img_paths = {r["path"] for r in regs if r["image"] and r["path"]}
    mod_paths = {m["path"] for m in mods if m["path"]}
    print("image region paths missing from modules:", img_paths - mod_paths)
    # every image allocation must be represented either by base or by path
    missing = []
    for r in regs:
        if not r["image"]:
            continue
        if r["path"] in mod_paths:
            continue
        if any(m["base"] <= r["base"] < m["base"] + (m["size"] or 1) for m in mods):
            continue
        missing.append((hex(r["base"]), r["path"]))
    print("image regions unaccounted:", missing)
    print("module sizes positive:", all(m["size"] > 0 for m in mods))
